        ImportField: "ignore" | "source_id" | "source_key" | "title" | "type" | "status" | "priority" | "assignee" | "reporter" | "creator" | "description" | "parent" | "labels" | "comment" | "created_at" | "updated_at" | "start_date" | "due_date" | "story_points" | "source_url" | "relations" | "attachment" | "sprint" | "resolution" | "watchers" | "original_estimate" | "source_container" | "custom";
